-- BattleBallServer: the quests of Ông Gôhan and the skill cards (docs 15.32).
-- PROPOSED by the assistant: every number; cards are paid in addition to the gold of a skill; the daily quests restart at 00:00 in Vietnam (UTC+7).
SET NAMES utf8mb4;

ALTER TABLE material_template MODIFY kind ENUM('FRAGMENT','UPGRADE_STONE','STAT_STONE','CRYSTAL_STONE','BOOK_MATERIAL','POTARA_SHARD','GEN_STONE','GEN_SLOT_STONE','SKILL_CARD') NOT NULL;

INSERT INTO material_template (template_id, material_key, kind, name_vi, item_template_id, buy_currency, price_wins, price_fixed, max_stack, icon_id, enabled, note, updated_by) VALUES
  (206, 'skill_card', 'SKILL_CARD', 'Thẻ nâng cấp', NULL, 'NONE', NULL, NULL, 999999, 13538, 1, 'Học hoặc nâng một kỹ năng tốn thẻ (skill_level.card_cost); chỉ nhận từ nhiệm vụ', 'V045');

ALTER TABLE skill_level ADD COLUMN card_cost SMALLINT UNSIGNED NOT NULL DEFAULT 0 AFTER gold_cost;
UPDATE skill_level l JOIN skill_template t ON t.skill_id = l.skill_id SET l.card_cost = t.slot + 1, l.updated_by = 'V045';

-- progress of the quests: the counters of the events (the quests of the types LEVEL and OWN_EARRING are read from the account, never stored).
-- period_key: '0' for a tutorial quest (done once), the day (Vietnam time, YYYY-MM-DD) for a daily quest.
CREATE TABLE IF NOT EXISTS quest_progress (
  account_id BIGINT UNSIGNED NOT NULL,
  quest_id   VARCHAR(24)     NOT NULL,
  period_key VARCHAR(10)     NOT NULL,
  progress   INT UNSIGNED    NOT NULL DEFAULT 0,
  claimed_at TIMESTAMP       NULL,
  PRIMARY KEY (account_id, quest_id, period_key),
  CONSTRAINT fk_quest_account FOREIGN KEY (account_id) REFERENCES account (account_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO balance_config (config_key, value_json, description, updated_by) VALUES
  ('quests', '{"quests":[{"id":"t01","kind":"TUTORIAL","title":"Điểm danh lần đầu","desc":"Gặp Ông Trưởng làng và điểm danh nhận quà hằng ngày.","type":"ATTENDANCE","target":1,"npc":"elder","reward":{"gold_wins":1,"gems":5,"items":[{"material":206,"qty":3}]}},{"id":"t02","kind":"TUTORIAL","title":"Học một kỹ năng","desc":"Mở bảng nhân vật, vào tab Kỹ năng rồi dùng thẻ nâng cấp và vàng để học hoặc nâng một kỹ năng.","type":"UPGRADE_SKILL","target":1,"npc":"","reward":{"gold_wins":1,"gems":5,"items":[{"material":206,"qty":4}]}},{"id":"t03","kind":"TUTORIAL","title":"Mua một món đồ","desc":"Đến Bunma, mua hoặc đổi mảnh lấy một món trang bị.","type":"GET_GEAR","target":1,"npc":"bunma","reward":{"gold_wins":2,"gems":5,"items":[{"material":206,"qty":4},{"material":201,"qty":2}]}},{"id":"t04","kind":"TUTORIAL","title":"Mặc trang bị","desc":"Mở bảng nhân vật, chọn \\"Xem đồ\\" rồi mặc món đồ vừa có vào nhân vật.","type":"EQUIP_ITEM","target":1,"npc":"","reward":{"gold_wins":1,"gems":3,"items":[{"material":206,"qty":3},{"material":201,"qty":1}]}},{"id":"t05","kind":"TUTORIAL","title":"Nâng cấp đồ","desc":"Đến Bà Hạt Mít, đặt món đồ và đá nâng cấp vào bảng rồi nâng cấp.","type":"UPGRADE_ITEM","target":1,"npc":"shop","reward":{"gold_wins":2,"gems":5,"items":[{"material":206,"qty":4},{"material":204,"qty":2}]}},{"id":"t06","kind":"TUTORIAL","title":"Đổi dòng GEN","desc":"Đến Bà Hạt Mít, dùng đá GEN đổi một dòng GEN của món đồ.","type":"GEN_REROLL","target":1,"npc":"shop","reward":{"gold_wins":2,"gems":5,"items":[{"material":206,"qty":5},{"material":205,"qty":1}]}},{"id":"t07","kind":"TUTORIAL","title":"Tập đánh Mộc nhân","desc":"Đến Mộc nhân và dùng nút nắm đấm hoặc kỹ năng đánh nó.","type":"TRAINING","target":1,"npc":"moc_nhan","reward":{"gold_wins":1,"gems":3,"items":[{"material":206,"qty":3}]}},{"id":"t08","kind":"TUTORIAL","title":"Thắng phó bản đầu tiên","desc":"Đến Cui, lên tàu vào một phó bản và hạ boss để thắng.","type":"DUNGEON_WIN","target":1,"npc":"cui","reward":{"go