ộc nhân","desc":"Đến Mộc nhân và đánh thử một lượt.","type":"TRAINING","target":1,"npc":"moc_nhan","reward":{"gold_wins":0.25,"gems":1,"items":[{"material":206,"qty":1}]}},{"id":"d05","kind":"DAILY","title":"Nâng cấp một món đồ","desc":"Đến Bà Hạt Mít và nâng cấp một món đồ (đá nâng cấp mua ở Bunma).","type":"UPGRADE_ITEM","target":1,"npc":"shop","reward":{"gold_wins":0.5,"gems":1,"items":[{"material":206,"qty":2},{"material":201,"qty":1}]}},{"id":"d06","kind":"DAILY","title":"Nâng cấp một kỹ năng","desc":"Mở bảng nhân vật, tab Kỹ năng, dùng thẻ để học hoặc nâng một kỹ năng.","type":"UPGRADE_SKILL","target":1,"npc":"","reward":{"gold_wins":0.5,"gems":1,"items":[{"material":206,"qty":3}]}}]}',
   'Nhiệm vụ Ông Gôhan: quests[] (id, kind TUTORIAL|DAILY, title, desc, type, target, npc, reward gold_wins/gems/items) (docs 15.32)', 'V045')
  ON DUPLICATE KEY UPDATE value_json = VALUES(value_json), description = VALUES(description), updated_by = VALUES(updated_by);

UPDATE static_data_version SET version = version + 1, updated_by = 'V045' WHERE domain IN ('BALANCE', 'SKILL');
